#!/usr/bin/env python3
"""
Civilization 6 District Adjacency Bonus Optimizer
"""

import sqlite3
import json
from collections import defaultdict
from typing import Dict, List, Tuple, Set

# Civ 6 District adjacency rules
# Format: {district_type: {bonus_condition: bonus_amount}}
DISTRICT_ADJACENCY_RULES = {
    'CAMPUS': {
        'MOUNTAIN': 2,
