        'ENCAMPMENT': 1,
        'INDUSTRIAL_ZONE': 1,
    },
    'ENCAMPMENT': {
        'AERODROME': 1,
        'COMMERCIAL_HUB': 1,
    },
}

# District placement rules
DISTRICT_PLACEMENT_RULES = {
    'CAMPUS': {
        'terrain': ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_TUNDRA', 'TERRAIN_DESERT', 'TERRAIN_SNOW'],
        'cannot_place_on': ['TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN'],
        'cannot_place_on_features': ['FEATURE_JUNGLE', 'FEATURE_SWAMP'],
    },
    'COMMERCIAL_HUB': {
        'terrain': ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_TUNDRA', 'TERRAIN_DESERT', 'TERRAIN_COAST'],
        'cannot_place_on': ['TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN'],
        'cannot_place_on_features': ['FEATURE_JUNGLE', 'FEATURE_SWAMP'],
    },
    'INDUSTRIAL_ZONE': {
        'terrain': ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_TUNDRA', 'TERRAIN_DESERT', 'TERRAIN_SNOW'],
        'cannot_place_on': ['TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN'],
        'cannot_place_on_features': ['FEATURE_JUNGLE', 'FEATURE_SWAMP'],
    },
    'THEATER_SQUARE': {
        'terrain': ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_TUNDRA', 'TERRAIN_DESERT', 'TERRAIN_SNOW'],
        'cannot_place_on': ['TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN'],
        'cannot_place_on_features': ['FEATURE_JUNGLE', 'FEATURE_SWAMP'],
    },
    'HOLY_SITE': {
        'terrain': ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_TUNDRA', 'TERRAIN_DESERT', 'TERRAIN_SNOW'],
