class Civ6Optimizer:
    """Optimizes district placement for maximum adjacency bonuses"""

    def __init__(self, map_db_path: str):
        self.map_db_path = map_db_path
        self.map = None
        self.cities = []

    def load_map(self):
        """Load map from SQLite database"""
        conn = sqlite3.connect(self.map_db_path)
        cursor = conn.cursor()

        # Get map dimensions
        cursor.execute("SELECT Width, Height FROM Map;")
        width, height = cursor.fetchone()
        self.map = Map(width, height)

        # Get all plots
        cursor.execute("""
            SELECT p.ID, p.TerrainType, p.ContinentType, p.IsImpassable,
                   pf.FeatureType, pr.ResourceType, pi.ImprovementType
            FROM Plots p
            LEFT JOIN PlotFeatures pf ON p.ID = pf.ID
            LEFT JOIN PlotResources pr ON p.ID = pr.ID
            LEFT JOIN PlotImprovements pi ON p.ID = pi.ID
            ORDER BY p.ID;
        """)

        for row in cursor.fetchall():
            plot_id, terrain, continent, impassable, feature, resource, improvement = row
            # Calculate x, y from ID
            x = plot_id % self.map.width
            y = plot_id // self.map.width

            plot = Plot(plot_id, x, y, terrain, feature, continent, resource, improvement)
            self.map.add_plot(plot)

        # Add rivers
        cursor.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers;")
        for row in cursor.fetchall():
            plot_id, is_ne, is_w, is_nw = row
            if is_ne or is_w or is_nw:
                plot = self.map.plots.get(plot_id)
                if plot:
                    plot.has_river = True

        conn.close()

    def can_place_district(self, plot: Plot, district_type: str) -> bool:
        """Check if a district can be placed on a plot"""
        rules = DISTRICT_PLACEMENT_RULES.get(district_type, {})
        terrain_ok = plot.terrain in rules.get('terrain', [])
        not_on_mountain = plot.terrain not in rules.get('cannot_place_on', [])
        not_on_feature = plot.feature not in rules.get('cannot_place_on_features', [])

        if not (terrain_ok and not_on_mountain and not_on_feature):
            return False

        if rules.get('must_be_adjacent_to_water', False):
            if not self.map.is_adjacent_to_water(plot.x, plot.y):
                return False

        return True

    def calculate_adjacency(self, plot: Plot, district_type: str, placed_districts: Dict[Tuple[int, int], str]) -> int:
        """Calculate adjacency bonus for a district"""
        if district_type not in DISTRICT_ADJACENCY_RULES:
            return 0

        rules = DISTRICT_ADJACENCY_RULES[district_type]
        total = 0

        # Check adjacent plots
        for nx, ny in self.map.get_adjacent_plots(plot.x, plot.y):
            adjacent_plot = self.map.get_plot(nx, ny)

            if not adjacent_plot:
                continue

            # Check for other districts
            if (nx, ny) in placed_districts:
                adjacent_district = placed_districts[(nx, ny)]
                if adjacent_district in rules:
                    total += rules[adjacent_district]

            # Check for terrain features
            if adjacent_plot.terrain == 'TERRAIN_GRASS_MOUNTAIN' and 'MOUNTAIN' in rules:
                total += rules['MOUNTAIN']

            # Check for features
            if adjacent_plot.feature == 'FEATURE_FOREST' and 'FOREST' in rules:
                total += rules['FOREST']
            if adjacent_plot.feature == 'FEATURE_JUNGLE' and 'RAINFOREST' in rules:
                total += rules['RAINFOREST']
            if adjacent_plot.feature == 'FEATURE_FLOODPLAINS_PLAINS':
                if 'RAINFOREST' in rules:  # Floodplains treated similarly
                    total += rules['RAINFOREST']
            if adjacent_plot.feature == 'FEATURE_GEOTHERMAL_FISSURE':
                if 'GEOTHERMAL_FISSURE' in rules:
                    total += rules['GEOTHERMAL_FISSURE']

            # Check for water adjacency
            if adjacent_plot.terrain == 'TERRAIN_COAST' and 'WATER' in rules:
                total += rules['WATER']

            # Check for rivers
            if adjacent_plot.has_river and 'RIVER' in rules:
                total += rules['RIVER']

            # Check for natural wonders
            if adjacent_plot.feature and 'NATURAL_WONDER' in adjacent_plot.feature.upper():
                if 'NATURAL_WONDER' in rules:
                    total += rules['NATURAL_WONDER']

            # Check for wonders (simplified - just check if plot has wonder improvement)
            if adjacent_plot.improvement and 'WONDER' in adjacent_plot.improvement.upper():
                if 'WONDER' in rules:
                    total += rules['WONDER']

            # Check for mines and quarries (simplified)
            if adjacent_plot.improvement == 'IMPROVEMENT_MINE' and 'MINE' in rules:
                total += rules['MINE']
            if adjacent_plot.improvement == 'IMPROVEMENT_QUARRY' and 'QUARRY' in rules:
                total += rules['QUARRY']
            if adjacent_plot.improvement == 'IMPROVEMENT_OIL_WELL' and 'OIL_WELL' in rules:
                total += rules['OIL_WELL']

            # Check for luxury resources (simplified)
            if adjacent_plot.resource and 'LUXURY' in adjacent_plot.resource.upper():
                if 'LUXURY_RESOURCE' in rules:
                    total += rules['LUXURY_RESOURCE']

        return total

    def evaluate_placement(self, placements: Dict[Tuple[int, int], str]) -> Tuple[int, Dict[str, int]]:
        """Evaluate total adjacency for a set of placements"""
        total = 0
        bonuses = {}

        for (x, y), district_type in placements.items():
            plot = self.map.get_plot(x, y)
            bonus = self.calculate_adjacency(plot, district_type, placements)
            bonuses[district_type] = bonus
            total += bonus

        return total, bonuses

    def optimize_city(self, city_center: Tuple[int, int], population: int) -> Dict:
        """Optimize district placement for a single city"""
        # Population determines number of districts (simplified: pop = districts + 1 for city center)
        num_districts = max(0, population - 1)

        # Candidate districts - prioritize those that can build near each other
        candidate_districts = ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE',
                             'HOLY_SITE', 'ENTERTAINMENT_COMPLEX', 'HARBOR', 'AERODROME', 'ENCAMPMENT']

        # Get all valid plots within 3 tiles of city center
        valid_plots = []
        cx, cy = city_center
        for x in range(max(0, cx - 3), min(self.map.width, cx + 4)):
            for y in range(max(0, cy - 3), min(self.map.height, cy + 4)):
                plot = self.map.get_plot(x, y)
                if plot and self.map.is_passable(plot):
                    # Check distance from city center
                    distance = math.sqrt((x - cx)**2 + (y - cy)**2)
                    if distance <= 3.1:  # Within 3 tiles
                        valid_plots.append((x, y))

        # Filter to plots where at least one district can be placed
        placeable_plots = []
        for x, y in valid_plots:
            plot = self.map.get_plot(x, y)
            for district_type in candidate_districts:
                if self.can_place_district(plot, district_type):
                    placeable_plots.append((x, y))
                    break

        print(f"Found {len(placeable_plots)} valid plots for city at ({cx}, {cy})")

        # Try different numbers of districts, starting from max
        best_score = -1
        best_placement = None

        # Generate all valid combinations
        from itertools import combinations, permutations

        for num_dists in range(min(num_districts, len(candidate_districts)), 0, -1):
            # Try all combinations of district types
            from itertools import combinations
            for district_types in combinations(candidate_districts, num_dists):
                # Try all ways to assign plots to these districts
                for plot_combination in combinations(placeable_plots, num_dists):
                    # Try all permutations (different plots can go to different districts)
                    for plot_assignment in permutations(plot_combination):
                        placed_districts = {}
                        valid = True

                        for district_type, (x, y) in zip(district_types, plot_assignment):
                            plot = self.map.get_plot(x, y)
                            if not self.can_place_district(plot, district_type):
                                valid = False
                                break
                            placed_districts[(x, y)] = district_type

                        if not valid or len(placed_districts) != num_dists:
                            continue

                        # Calculate total adjacency
                        total_adjacency, adjacency_bonuses = self.evaluate_placement(placed_districts)

                        if total_adjacency > best_score:
                            best_score = total_adjacency
                            best_placement = {
                                'city_center': list(city_center),
                                'placements': {dt: [p[0], p[1]] for dt, p in zip(district_types, plot_assignment)},
                                'adjacency_bonuses': adjacency_bonuses,
                                'total_adjacency': total_adjacency
                            }

            # If we found a good placement with this number of districts, we can stop
            # But let's try a few more to be sure
            if best_score > 0:
                pass

        return best_placement if best_placement else {
            'city_center': list(city_center),
            'placements': {},
            'adjacency_bonuses': {},
            'total_adjacency': 0
        }

    def find_best_city_location(self, population: int) -> Tuple[int, int]:
        """Find the best location for a city"""
        best_score = -1
        best_location = None

        # Try all passable plots as potential city centers
        for (x, y), plot in self.map.plots.items():
            if not self.map.is_passable(plot):
                continue

            # Heuristic: prefer grass/plains near water with good district potential
            score = 0
            if plot.terrain == 'TERRAIN_GRASS':
                score += 10
            elif plot.terrain == 'TERRAIN_PLAINS':
                score += 8

            # Bonus for being near water
            if self.map.is_adjacent_to_water(x, y):
                score += 10

            # Check if we have good plots nearby for districts
            valid_districts_nearby = 0
            for nx, ny in self.map.get_adjacent_plots(x, y):
                adj_plot = self.map.get_plot(nx, ny)
                if adj_plot and self.map.is_passable(adj_plot):
                    # Count how many different districts can be placed
                    for district in DISTRICT_PLACEMENT_RULES:
                        if self.can_place_district(adj_plot, district):
                            valid_districts_nearby += 1

            score += valid_districts_nearby

            if score > best_score:
                best_score = score
                best_location = (x, y)

        return best_location if best_location else (self.map.width // 2, self.map.height // 2)

    def optimize(self, num_cities: int, population: int) -> Dict:
        """Optimize placement for multiple cities"""
        if num_cities == 1:
            # Find best city location
            city_location = self.find_best_city_location(population)
            print(f"Best city location: {city_location}")
            return self.optimize_city(city_location, population)
        else:
            # Multiple cities - simplified for now
            cities = []
            placements = {}
            adjacency_bonuses = {}
            total_adjacency = 0

            used_positions = set()

            for i in range(num_cities):
                # Find best location not too close to other cities
                best_location = None
                best_score = -1

                for (x, y), plot in self.map.plots.items():
                    if (x, y) in used_positions or not self.map.is_passable(plot):
                        continue

                    # Check distance from other cities
                    too_close = False
                    for city_pos in used_positions:
                        if math.sqrt((x - city_pos[0])**2 + (y - city_pos[1])**2) < 5:
                            too_close = True
                            break

                    if too_close:
                        continue

                    score = 0
                    if plot.terrain == 'TERRAIN_GRASS':
                        score += 10
                    elif plot.terrain == 'TERRAIN_PLAINS':
                        score += 8

                    if self.map.is_adjacent_to_water(x, y):
                        score += 5

                    if score > best_score:
                        best_score = score
                        best_location = (x, y)

                if best_location:
                    used_positions.add(best_location)
                    cities.append({'center': list(best_location)})

            # Optimize districts for each city
            for city in cities:
                city_result = self.optimize_city(tuple(city['center']), population)
                placements.update(city_result['placements'])
                for district, bonus in city_result['adjacency_bonuses'].items():
                    if district not in adjacency_bonuses:
                        adjacency_bonuses[district] = 0
                    adjacency_bonuses[district] += bonus
                    total_adjacency += bonus

            return {
                'cities': cities,
                'placements': placements,
                'adjacency_bonuses': adjacency_bonuses,
                'total_adjacency': total_adjacency
            }


def main():
    """Main function"""
    # Load scenario
    with open('/data/scenario_3/scenario.json', 'r') as f:
        scenario = json.load(f)

    print(f"Optimizing scenario: {scenario['id']}")
    print(f"Description: {scenario['description']}")
    print(f"Number of cities: {scenario['num_cities']}")
    print(f"Population: {scenario['population']}")
    print(f"Civilization: {scenario['civilization']}")

    # Create optimizer
    optimizer = Civ6Optimizer('/data/maps/e2e_test_case_0.Civ6Map')
    optimizer.load_map()

    print(f"\nMap loaded: {optimizer.map.width} x {optimizer.map.height}")

    # Optimize
    result = optimizer.optimize(scenario['num_cities'], scenario['population'])

    print(f"\nOptimal placement found:")
    print(f"Total adjacency: {result['total_adjacency']}")
    print(f"Adjacency bonuses: {result['adjacency_bonuses']}")
    print(f"Placements: {result['placements']}")

    # Save result
    with open('/output/scenario_3.json', 'w') as f:
        json.dump(result, f, indent=2)

    print(f"\nSolution saved to /output/scenario_3.json")


if __name__ == '__main__':
    main()

