            FROM Plots p
            LEFT JOIN PlotFeatures pf ON p.ID = pf.ID
            LEFT JOIN PlotResources pr ON p.ID = pr.ID
            LEFT JOIN PlotImprovements pi ON p.ID = pi.ID
            ORDER BY p.ID;
        """)

        for row in cursor.fetchall():
            plot_id, terrain, continent, impassable, feature, resource, improvement = row
            # Calculate x, y from ID
            x = plot_id % self.width
            y = plot_id // self.width

            self.plots[(x, y)] = {
