class Civ6Optimizer:
    """Optimizer for district placement"""

    def __init__(self, map_db_path: str):
        self.map_db_path = map_db_path
        self.map = None

    def load_map(self):
        """Load map from SQLite database"""
        conn = sqlite3.connect(self.map_db_path)
        cursor = conn.cursor()

        # Get map dimensions
        cursor.execute("SELECT Width, Height FROM Map;")
        width, height = cursor.fetchone()
        self.width = width
        self.height = height

        # Get all plots
        self.plots = {}
        cursor.execute("""
            SELECT p.ID, p.TerrainType, p.ContinentType, p.IsImpassable,
                   pf.FeatureType, pr.ResourceType, pi.ImprovementType
            FROM Plots p
            LEFT JOIN PlotFeatures pf ON p.ID = pf.ID
            LEFT JOIN PlotResources pr ON p.ID = pr.ID
            LEFT JOIN PlotImprovements pi ON p.ID = pi.ID
            ORDER BY p.ID;
        """)

        for row in cursor.fetchall():
            plot_id, terrain, continent, impassable, feature, resource, improvement = row
            # Calculate x, y from ID
            x = plot_id % self.width
            y = plot_id // self.width

            self.plots[(x, y)] = {
                'terrain': terrain,
                'feature': feature,
                'resource': resource,
                'improvement': improvement,
                'has_river': False,
            }

        # Add rivers
        cursor.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers;")
        for row in cursor.fetchall():
            plot_id, is_ne, is_w, is_nw = row
            if is_ne or is_w or is_nw:
                x = plot_id % self.width
                y = plot_id // self.width
                if (x, y) in self.plots:
                    self.plots[(x, y)]['has_river'] = True

        conn.close()

    def get_adjacent(self, x: int, y: int) -> List[Tuple[int, int]]:
        """Get adjacent plot coordinates"""
        adjacent = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < self.width and 0 <= ny < self.height:
                    adjacent.append((nx, ny))
        return adjacent

    def can_place_district(self, x: int, y: int, district_type: str) -> bool:
        """Check if district can be placed"""
        if (x, y) not in self.plots:
            return False

        plot = self.plots[(x, y)]
        rules = DISTRICT_PLACEMENT_RULES.get(district_type, {})

        # Check terrain
        if plot['terrain'] not in rules.get('terrain', []):
            return False

        # Check cannot place on
        if plot['terrain'] in rules.get('cannot_place_on', []):
            return False

        # Check cannot place on features
        if plot['feature'] in rules.get('cannot_place_on_features', []):
            return False

        # Check must be adjacent to water
        if rules.get('must_be_adjacent_to_water', False):
            if not self.is_adjacent_to_water(x, y):
                return False

        return True

    def is_adjacent_to_water(self, x: int, y: int) -> bool:
        """Check if adjacent to water"""
        for nx, ny in self.get_adjacent(x, y):
            if (nx, ny) in self.plots:
                terrain = self.plots[(nx, ny)]['terrain']
                if terrain in ['TERRAIN_COAST', 'TERRAIN_OCEAN']:
                    return True
        return False

    def calculate_adjacency(self, x: int, y: int, district_type: str, placed: Dict[Tuple[int, int], str]) -> int:
        """Calculate adjacency for a district"""
        if district_type not in DISTRICT_ADJACENCY_RULES:
            return 0

        rules = DISTRICT_ADJACENCY_RULES[district_type]
        total = 0

        for nx, ny in self.get_adjacent(x, y):
            if (nx, ny) not in self.plots:
                continue

            plot = self.plots[(nx, ny)]

            # Check for other districts
            if (nx, ny) in placed:
                adj_district = placed[(nx, ny)]
                if adj_district in rules:
                    total += rules[adj_district]

            # Check terrain
            if plot['terrain'] == 'TERRAIN_GRASS_MOUNTAIN' and 'MOUNTAIN' in rules:
                total += rules['MOUNTAIN']

            # Check features
            if plot['feature'] == 'FEATURE_FOREST' and 'FOREST' in rules:
                total += rules['FOREST']
            if plot['feature'] == 'FEATURE_JUNGLE' and 'RAINFOREST' in rules:
                total += rules['RAINFOREST']
            if plot['feature'] == 'FEATURE_FLOODPLAINS_PLAINS' and 'RAINFOREST' in rules:
                total += rules['RAINFOREST']
            if plot['feature'] == 'FEATURE_GEOTHERMAL_FISSURE' and 'GEOTHERMAL_FISSURE' in rules:
                total += rules['GEOTHERMAL_FISSURE']

            # Check water
            if plot['terrain'] == 'TERRAIN_COAST' and 'WATER' in rules:
                total += rules['WATER']

            # Check river
            if plot['has_river'] and 'RIVER' in rules:
                total += rules['RIVER']

            # Check resources
            if plot['resource'] and 'LUXURY' in plot['resource'].upper() and 'LUXURY_RESOURCE' in rules:
                total += rules['LUXURY_RESOURCE']

        return total

    def find_best_city_location(self) -> Tuple[int, int]:
        """Find best city center location"""
        best_score = -1
        best_loc = None

        for (x, y), plot in self.plots.items():
            # Skip impassable
            if plot['terrain'] in ['TERRAIN_OCEAN', 'TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN']:
                continue

            score = 0

            # Prefer grass
            if plot['terrain'] == 'TERRAIN_GRASS':
                score += 10
            elif plot['terrain'] == 'TERRAIN_PLAINS':
                score += 8

            # Near water is good
            if self.is_adjacent_to_water(x, y):
                score += 10

            # Good adjacent tiles
            for nx, ny in self.get_adjacent(x, y):
                if (nx, ny) in self.plots:
                    adj_plot = self.plots[(nx, ny)]
                    if adj_plot['terrain'] not in ['TERRAIN_OCEAN', 'TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN']:
                        score += 1

            if score > best_score:
                best_score = score
                best_loc = (x, y)

        return best_loc if best_loc else (self.width // 2, self.height // 2)

    def optimize_city(self, city_center: Tuple[int, int], population: int) -> Dict:
        """Optimize single city using smarter selection"""
        max_districts = max(0, population - 1)
        placed = {}

        # Get all valid plots within 3 tiles
        valid_plots = []
        cx, cy = city_center
        for x in range(max(0, cx - 3), min(self.width, cx + 4)):
            for y in range(max(0, cy - 3), min(self.height, cy + 4)):
                if (x, y) not in self.plots:
                    continue
                plot = self.plots[(x, y)]
                # Check passable
                if plot['terrain'] in ['TERRAIN_OCEAN', 'TERRAIN_MOUNTAIN', 'TERRAIN_GRASS_MOUNTAIN']:
                    continue
                # Check distance
                if math.sqrt((x - cx)**2 + (y - cy)**2) <= 3.1:
                    valid_plots.append((x, y))

        # Try all possible numbers of districts from max down to 1
        best_result = None
        best_score = -1

        # Priority order for districts
        all_districts = ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HARBOR', 'HOLY_SITE',
                        'AERODROME', 'ENCAMPMENT']

        from itertools import combinations

        # Try different numbers of districts
        for num_districts in range(max_districts, 0, -1):
            # Try combinations of districts
            for district_combo in combinations(all_districts, num_districts):
                # Greedily assign plots to these districts
                local_placements = {}
                local_placed = {}

                # For each district in the combo, find best plot
                for district_type in district_combo:
                    best_plot_score = -1
                    best_plot = None

                    for x, y in valid_plots:
                        if (x, y) in local_placements or (x, y) == city_center:
                            continue

                        if not self.can_place_district(x, y, district_type):
                            continue

                        # Calculate adjacency
                        bonus = self.calculate_adjacency(x, y, district_type, local_placed)

                        # Bonus for being closer to center
                        dist_bonus = 0.5 * (3 - math.sqrt((x - cx)**2 + (y - cy)**2))
                        score = bonus + dist_bonus

                        if score > best_plot_score:
                            best_plot_score = score
                            best_plot = (x, y)

                    if best_plot:
                        local_placements[best_plot] = district_type
                        local_placed[best_plot] = district_type

                # Check if we placed all districts
                if len(local_placements) == num_districts:
                    # Calculate total adjacency
                    total_adj = 0
                    bonuses = {}
                    for (x, y), dt in local_placements.items():
                        bonus = self.calculate_adjacency(x, y, dt, local_placed)
                        bonuses[dt] = bonus
                        total_adj += bonus

                    if total_adj > best_score:
                        best_score = total_adj
                        # Convert to output format
                        output_placements = {dt: [x, y] for (x, y), dt in local_placements.items()}
                        best_result = {
                            'city_center': list(city_center),
                            'placements': output_placements,
                            'adjacency_bonuses': bonuses,
                            'total_adjacency': total_adj
                        }

            # If we found a good result with this number, keep trying lower numbers
            # to see if we can get even better per-district average

        return best_result if best_result else {
            'city_center': list(city_center),
            'placements': {},
            'adjacency_bonuses': {},
            'total_adjacency': 0
        }

    def optimize(self, num_cities: int, population: int) -> Dict:
        """Optimize placement"""
        if num_cities == 1:
            city_location = self.find_best_city_location()
            print(f"Best city location: {city_location}")
            return self.optimize_city(city_location, population)
        else:
            # Multi-city (not used in this scenario)
            return {
                'cities': [{'center': list(self.find_best_city_location())}],
                'placements': {},
                'adjacency_bonuses': {},
                'total_adjacency': 0
            }


def main():
    """Main function"""
    with open('/data/scenario_3/scenario.json', 'r') as f:
        scenario = json.load(f)

    print(f"Optimizing scenario: {scenario['id']}")
    print(f"Description: {scenario['description']}")
    print(f"Number of cities: {scenario['num_cities']}")
    print(f"Population: {scenario['population']}")
    print(f"Civilization: {scenario['civilization']}")

    optimizer = Civ6Optimizer('/data/maps/e2e_test_case_0.Civ6Map')
    optimizer.load_map()

    print(f"\nMap loaded: {optimizer.width} x {optimizer.height}")

    result = optimizer.optimize(scenario['num_cities'], scenario['population'])

    print(f"\nOptimal placement found:")
    print(f"Total adjacency: {result['total_adjacency']}")
    print(f"Adjacency bonuses: {result['adjacency_bonuses']}")
    print(f"Placements: {result['placements']}")

    with open('/output/scenario_3.json', 'w') as f:
        json.dump(result, f, indent=2)

    print(f"\nSolution saved to /output/scenario_3.json")


if __name__ == '__main__':
    main()

